import {FarmGame, WIDTH, HEIGHT} from './game-core.js';
import {FarmAudio} from './audio.js';

const $=id=>document.getElementById(id);
const canvas=$('game'),ctx=canvas.getContext('2d',{alpha:false}),game=new FarmGame(),audio=new FarmAudio();
const keys=new Set(),touch=[new Set(),new Set()],colours=['#b9e6ed','#f4c571'];
let sprites,background,loaded=false,countLeft=0,counting=false,countPaused=false,lastTime=0,lastCount=0,nextCluck=4,reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
// Use source rectangles directly so the generated feather alpha stays intact.
const atlas={pearl:[50,22,423,490],rusty:[550,22,414,490],crate:[1010,89,504,389],bale:[14,535,513,436],pot:[549,533,449,419],seed:[1236,574,94,57]};
function sprite(name,x,y,w,h,context=ctx){if(!sprites)return;const a=atlas[name];context.drawImage(sprites,...a,x,y,w,h);}
function portrait(id,name){const el=$(id),c=el.getContext('2d');c.clearRect(0,0,el.width,el.height);const h=el.height*1.06,w=h*.86;sprite(name,(el.width-w)/2,4,w,h,c);}
function loadImage(path){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('An image did not load.'));img.src=path;});}
function inputs(){return [{x:Number(keys.has('KeyD')||touch[0].has('right'))-Number(keys.has('KeyA')||touch[0].has('left')),y:Number(keys.has('KeyS')||touch[0].has('down'))-Number(keys.has('KeyW')||touch[0].has('up'))},{x:Number(keys.has('ArrowRight')||touch[1].has('right'))-Number(keys.has('ArrowLeft')||touch[1].has('left')),y:Number(keys.has('ArrowDown')||touch[1].has('down'))-Number(keys.has('ArrowUp')||touch[1].has('up'))}];}
function clearInputs(){keys.clear();touch.forEach(s=>s.clear());}
function overlay(card){$('overlay').hidden=false;for(const id of ['startCard','countdown','pauseCard','resultCard'])$(id).hidden=id!==card;$('overlay').classList.toggle('counting',card==='countdown');}
function announce(text){$('announcer').textContent=text;}
function sync(){const seconds=Math.ceil(game.remaining);$('score1').textContent=game.players[0].score;$('score2').textContent=game.players[1].score;$('timer').textContent=`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;$('timer').setAttribute('aria-label',`${seconds} seconds remaining`);$('timerFill').style.width=`${game.remaining/60*100}%`;$('timer').parentElement.classList.toggle('urgent',game.remaining<=10);}
function startRound(){if(!loaded)return;void audio.unlock();clearInputs();game.reset();counting=true;countPaused=false;countLeft=3;lastCount=3;nextCluck=4;lastTime=performance.now();overlay('countdown');$('countdown').textContent='3';$('roundLabel').textContent='get ready';$('pause').hidden=false;sync();canvas.focus({preventScroll:true});announce('get ready. three, two, one.');}
function pause(){if(counting){countPaused=true;}else if(!game.pause())return;clearInputs();overlay('pauseCard');$('pause').hidden=true;$('roundLabel').textContent='paused';$('resume').focus({preventScroll:true});announce('game paused.');}
function resume(){if(countPaused){countPaused=false;overlay('countdown');}else{if(!game.resume())return;$('overlay').hidden=true;}void audio.unlock();lastTime=performance.now();$('roundLabel').textContent=counting?'get ready':'the seed scramble';$('pause').hidden=false;canvas.focus({preventScroll:true});announce('game resumed.');}
function finish(){clearInputs();$('pause').hidden=true;$('roundLabel').textContent='time’s up';const [p1,p2]=game.players;const draw=game.winner==='draw';$('winnerTitle').textContent=draw?'a perfect tie.':`${game.players[game.winner].name} rules the roost.`;$('winnerMessage').textContent=draw?`both hens found ${p1.score} seeds. another round?`:`player ${game.winner+1} wins by ${Math.abs(p1.score-p2.score)} ${Math.abs(p1.score-p2.score)===1?'seed':'seeds'}. nicely pecked.`;$('final1').textContent=p1.score;$('final2').textContent=p2.score;
  const wc=$('winnerPortrait').getContext('2d');wc.clearRect(0,0,180,150);if(draw){sprite('pearl',6,5,90,135,wc);sprite('rusty',89,5,90,135,wc);}else portrait('winnerPortrait',game.players[game.winner].name);
  overlay('resultCard');$('again').focus({preventScroll:true});audio.bell(true);announce(`${$('winnerTitle').textContent} pearl: ${p1.score} seeds. rusty: ${p2.score} seeds.`);
}
function shadow(x,y,rx,ry,opacity=.22){ctx.save();ctx.fillStyle=`rgba(25,22,10,${opacity})`;ctx.beginPath();ctx.ellipse(x+5,y+5,rx,ry,0,0,Math.PI*2);ctx.fill();ctx.restore();}
function drawHen(p,time){const moving=p.moving&&game.status==='playing',bob=!reducedMotion&&moving?Math.abs(Math.sin(p.walk))*4:0;shadow(p.x,p.y,29,12,.29);
  ctx.save();ctx.translate(p.x,p.y);ctx.strokeStyle=colours[p.id];ctx.globalAlpha=.7;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,3,35,16,0,0,Math.PI*2);ctx.stroke();ctx.restore();
  ctx.save();ctx.translate(p.x,p.y-bob);ctx.scale(p.facing,1);if(!reducedMotion){ctx.rotate(moving?Math.sin(p.walk)*.035:Math.sin(time*.0015+p.id)*.009);if(p.peck>0)ctx.rotate(Math.sin(p.peck/.24*Math.PI)*.17);}sprite(p.name,-44,-98,92,108);ctx.restore();
  ctx.save();ctx.font='600 13px "DM Sans", sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle='#173126e8';ctx.beginPath();ctx.roundRect(p.x-16,p.y+24,32,24,7);ctx.fill();ctx.fillStyle=colours[p.id];ctx.fillText(`p${p.id+1}`,p.x,p.y+36);ctx.restore();
}
function drawProp(p){const dims=p.type==='bale'?[132,105]:p.type==='crate'?[116,90]:[87,81];shadow(p.x,p.y,p.r+4,p.r*.42,.28);sprite(p.type,p.x-dims[0]/2,p.y-dims[1]*.7,dims[0],dims[1]);}
function render(time){ctx.clearRect(0,0,WIDTH,HEIGHT);if(!background)return;ctx.drawImage(background,0,0,WIDTH,HEIGHT);
  // Only genuinely uncovered grains are shown or collectable.
  for(const seed of game.seeds){if(seed.taken||game.covered(seed))continue;ctx.save();ctx.translate(seed.x,seed.y);const glow=ctx.createRadialGradient(0,0,2,0,0,23);glow.addColorStop(0,'rgba(255,235,145,.75)');glow.addColorStop(.4,'rgba(255,209,90,.36)');glow.addColorStop(1,'rgba(255,197,65,0)');ctx.fillStyle=glow;ctx.fillRect(-23,-23,46,46);ctx.rotate(seed.angle);ctx.shadowColor='#ffe99b';ctx.shadowBlur=14;sprite('seed',-12,-7.5,24,15);ctx.restore();}
  const entities=[...game.props.map(p=>({y:p.y+10,draw:()=>drawProp(p)})),...game.players.map(p=>({y:p.y,draw:()=>drawHen(p,time)}))];entities.sort((a,b)=>a.y-b.y).forEach(e=>e.draw());
  for(const p of game.particles){ctx.save();ctx.globalAlpha=Math.min(1,p.life*3);ctx.font='700 19px "DM Sans", sans-serif';ctx.textAlign='center';ctx.strokeStyle='#283220';ctx.lineWidth=3;const y=p.y-35-(.65-p.life)*38;ctx.strokeText('+1',p.x,y);ctx.fillStyle=colours[p.player];ctx.fillText('+1',p.x,y);ctx.restore();}
}
function frame(time){const dt=lastTime?Math.max(0,(time-lastTime)/1000):0;lastTime=time;
  if(counting&&!countPaused){countLeft-=dt;const n=Math.ceil(countLeft);if(n!==lastCount&&n>0){lastCount=n;$('countdown').textContent=n;audio.bell();}if(countLeft<=0){counting=false;game.begin();$('overlay').hidden=true;$('roundLabel').textContent='the seed scramble';audio.cluck(0,true);announce('go! collect the most seeds in one minute.');}}
  else if(game.status==='playing'){const events=game.step(dt,inputs());for(const e of events){if(e.type==='collect')audio.cluck(e.player);if(e.type==='end')finish();}if(game.elapsed>nextCluck&&game.status==='playing'){audio.cluck(Math.random()<.5?0:1);nextCluck=game.elapsed+3+Math.random()*4;}sync();}
  render(time);requestAnimationFrame(frame);
}
const movementKeys=new Set(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowLeft','ArrowDown','ArrowRight']);
window.addEventListener('keydown',e=>{if(e.metaKey||e.ctrlKey||e.altKey)return;if(movementKeys.has(e.code)){e.preventDefault();keys.add(e.code);}if(e.code==='ShiftLeft'&&!e.repeat){e.preventDefault();if(game.status==='playing'||counting&&!countPaused)pause();else if(game.status==='paused'||countPaused)resume();}if(e.code==='Space'&&!e.repeat&&e.target===canvas){e.preventDefault();if(game.status==='ready'||game.status==='ended')startRound();}});
window.addEventListener('keyup',e=>{if(movementKeys.has(e.code)){e.preventDefault();keys.delete(e.code);}});
window.addEventListener('blur',()=>{clearInputs();if(game.status==='playing'||counting&&!countPaused)pause();});
document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInputs();if(game.status==='playing'||counting&&!countPaused)pause();}});
for(const id of ['start','again','restartPaused'])$(id).addEventListener('click',startRound);$('pause').addEventListener('click',pause);$('resume').addEventListener('click',resume);
$('sound').addEventListener('click',()=>{void audio.unlock();audio.setMuted(!audio.muted);$('sound').setAttribute('aria-pressed',String(audio.muted));$('sound').setAttribute('aria-label',audio.muted?'unmute chicken sounds':'mute chicken sounds');$('soundIcon').textContent=audio.muted?'♪':'♫';$('soundText').textContent=audio.muted?'sound off':'sound on';if(!audio.muted)audio.cluck(0,true);});
if(!document.fullscreenEnabled)$('fullscreen').hidden=true;
$('fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.querySelector('.app').requestFullscreen();}catch{announce('full screen is unavailable in this browser.');}});
document.addEventListener('fullscreenchange',()=>{$('fullscreen').setAttribute('aria-label',document.fullscreenElement?'exit full screen':'enter full screen');});
for(const button of document.querySelectorAll('.pad button')){const {player,dir}=button.dataset;button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);touch[Number(player)].add(dir);});for(const event of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(event,()=>touch[Number(player)].delete(dir));}
async function prepare(){try{[sprites,background]=await Promise.all([loadImage('./assets/sprites.png'),loadImage('./assets/farmyard.png')]);loaded=true;portrait('portrait1','pearl');portrait('portrait2','rusty');$('start').disabled=false;$('start').textContent='let’s play →';}catch{$('start').disabled=false;$('start').textContent='reload the farmyard ↻';$('start').onclick=()=>location.reload();announce('the artwork could not load. please reload the farmyard.');}}
void prepare();sync();requestAnimationFrame(frame);

// Optional browser-standard actions use the same round state as the visible controls.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'read_chicken_game',description:'Read the current round timer, scores and winner.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){return {...game.snapshot(),status:countPaused?'paused':counting?'countdown':game.status};}});register({name:'control_chicken_round',description:'Start a fresh chicken game, pause the current round or resume it. Starting resets both scores.',inputSchema:{type:'object',properties:{action:{type:'string',enum:['start','pause','resume']}},required:['action'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!['start','pause','resume'].includes(input.action))throw new Error('Choose start, pause or resume.');if(!loaded)throw new Error('The farmyard is still loading.');if(input.action==='start')startRound();else if(input.action==='pause'){if(game.status!=='playing'&&!(counting&&!countPaused))throw new Error('No active round to pause.');pause();}else{if(game.status!=='paused'&&!countPaused)throw new Error('The game is not paused.');resume();}return {...game.snapshot(),status:countPaused?'paused':counting?'countdown':game.status};}});}
